package io.orbit.probe.cert;

import javax.net.ssl.KeyManagerFactory;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLServerSocket;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.TrustManagerFactory;
import javax.net.ssl.X509ExtendedTrustManager;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.InetAddress;
import java.nio.file.Path;
import java.security.KeyStore;

/** Local TLS server with a self-signed certificate generated by keytool (JDK) for the tests. */
final class TestTlsServer implements AutoCloseable {

    static final char[] PASSWORD = "changeit".toCharArray();

    private final SSLServerSocket server;
    private final Thread acceptor;
    final Path keyStore;

    private TestTlsServer(Path keyStore, SSLServerSocket server) {
        this.keyStore = keyStore;
        this.server = server;
        this.acceptor = Thread.ofVirtual().start(this::accept);
    }

    /** Self-signed certificate for localhost valid for {@code validityDays}. */
    static TestTlsServer start(Path dir, int validityDays) throws Exception {
        Path keyStore = dir.resolve("server-" + validityDays + ".p12");
        String keytool = Path.of(System.getProperty("java.home"), "bin", "keytool").toString();
        Process process = new ProcessBuilder(keytool, "-genkeypair", "-alias", "server", "-keyalg", "EC",
                "-groupname", "secp256r1", "-dname", "CN=localhost, O=Orbit Test", "-ext", "SAN=dns:localhost",
                "-validity", String.valueOf(validityDays), "-storetype", "PKCS12", "-keystore", keyStore.toString(),
                "-storepass", new String(PASSWORD), "-keypass", new String(PASSWORD))
                .redirectErrorStream(true).start();
        process.getInputStream().readAllBytes();
        if (process.waitFor() != 0) {
            throw new IllegalStateException("keytool failed");
        }
        KeyStore store = load(keyStore);
        KeyManagerFactory keys = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        keys.init(store, PASSWORD);
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(keys.getKeyManagers(), null, null);
        SSLServerSocket socket = (SSLServerSocket) context.getServerSocketFactory()
                .createServerSocket(0, 10, InetAddress.getLoopbackAddress());
        return new TestTlsServer(keyStore, socket);
    }

    /** A trust manager that trusts only this server's certificate. */
    X509ExtendedTrustManager trustingThisServer() throws Exception {
        TrustManagerFactory factory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        factory.init(load(keyStore));
        return (X509ExtendedTrustManager) factory.getTrustManagers()[0];
    }

    int port() {
        return server.getLocalPort();
    }

    private static KeyStore load(Path path) throws Exception {
        KeyStore store = KeyStore.getInstance("PKCS12");
        try (FileInputStream in = new FileInputStream(path.toFile())) {
            store.load(in, PASSWORD);
        }
        return store;
    }

    private void accept() {
        while (!server.isClosed()) {
            try (SSLSocket client = (SSLSocket) server.accept()) {
                client.startHandshake();
            } catch (IOException e) {
                // client closed early or server stopped
            }
        }
    }

    @Override
    public void close() throws IOException {
        server.close();
    }
}
